import React from 'react';

interface Props {
  title?: string;
  onToggleSidebar?: () => void;
}

export const Navbar: React.FC<Props> = ({ title = 'Admin Panel', onToggleSidebar }) => {
  return (
    <header style={{
      height: 56,
      background: '#ffffff',
      color: 'white',
      display: 'flex',
      alignItems: 'center',
      padding: '0 16px',
      gap: 12,
      boxShadow: '0 1px 0 rgba(255,255,255,0.03)'
    }}>
      <button
        onClick={onToggleSidebar}
        style={{
          background: 'none',
          border: 'none',
          color: 'white',
          cursor: 'pointer',
          padding: '4px 6px',
          borderRadius: 4,
          display: 'flex',
          flexDirection: 'column',
          gap: 4,
          alignItems: 'center',
        }}
        aria-label="Toggle sidebar"
      >
        <span style={{ display: 'block', width: 18, height: 2, background: 'white', borderRadius: 2 }} />
        <span style={{ display: 'block', width: 18, height: 2, background: 'white', borderRadius: 2 }} />
        <span style={{ display: 'block', width: 18, height: 2, background: 'white', borderRadius: 2 }} />
      </button>
      <h1 style={{ fontSize: 16, margin: 0 }}>{title}</h1>
    </header>
  );
};

export default Navbar;
